using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using System.Net;using System.Net.Http.Json;using System.Text.Json;using Microsoft.AspNetCore.Identity;using System.IO.Compression;using ClosedXML.Excel;
namespace Decont.Tests;
public class ReceiptTests {
 static Master Master(string kind,string code,object data)=>new(){Kind=kind,Code=code,NameRo=code,NameEn=code,From=new(2020,1,1),Json=Serialization.Write(data)};
 static (Report,List<Master>) Fixture(){var rates=new[]{0,11,21}.Select(p=>Master("vat",p.ToString(),new{rate=p,salesTaxGroup="VDOM",itemTaxGroup="G"+p})).ToList();var data=new ExpenseData("Supplier","18546294","B001","2026-01-01","RO","Receipt","GENERAL","Business receipt","Personal",null,"CC",null,332,"RON",[new(rates[0].Id,100,0),new(rates[1].Id,100,11),new(rates[2].Id,100,21)],true,true,"RON");var r=new Report{Purpose="Multiple receipts",ManagerId="manager",Lines=[new(){Position=1,EstimatedRon=332,Json=Serialization.Write(data),Evidence=[new(){Scan="Clean"}]}]};rates.Add(Master("expenseTypes","GENERAL",new{}));rates.Add(Master("costCenters","CC",new{erpCode="CC"}));return(r,rates);}
 [Fact]public void MixedVatPreservesEachBaseAndPaidVatAndReconstructsReceipt(){var(r,masters)=Fixture();Assert.Empty(Rules.VatIssues(r.Lines[0],masters));Assert.Equal(332,Rules.TaxTotal(r.Lines[0].Data()));Assert.DoesNotContain(Rules.Validate(r,masters),p=>p.Blocking);var d=r.Lines[0].Data();r.Lines[0].Json=Serialization.Write(d with{Amount=333});Assert.Contains(Rules.VatIssues(r.Lines[0],masters),p=>p.Code=="vat_total");}
 [Fact]public void ZeroVatCannotContainPaidVatAndDuplicatePercentagesAreRejected(){var(r,m)=Fixture();var d=r.Lines[0].Data();r.Lines[0].Json=Serialization.Write(d with{Taxes=[new(d.Taxes[0].RateId,100,1),new(d.Taxes[1].RateId,100,11),new(d.Taxes[2].RateId,100,21)]});Assert.Contains(Rules.VatIssues(r.Lines[0],m),p=>p.Code=="vat_arithmetic");var duplicate=Master("vat","another-zero",new{rate=0});m.Add(duplicate);r.Lines[0].Json=Serialization.Write(d with{Taxes=[new(d.Taxes[0].RateId,100,0),new(duplicate.Id,100,0)]});Assert.Contains(Rules.VatIssues(r.Lines[0],m),p=>p.Code=="vat_duplicate");}
 [Theory][InlineData("RO",false)][InlineData("DE",false)]public void NoCompanyCuiOrForeignReceiptsRequireNoSupplierOrVat(string country,bool has){var(r,m)=Fixture();r.Lines[0].EstimatedRon=100;r.Lines[0].Json=Serialization.Write(r.Lines[0].Data() with{Country=country,HasCompanyCui=has,Cui=null,Supplier="",Invoice="",Taxes=[],Amount=100});var states=Rules.FieldStates(r.Lines[0].Data(),m);Assert.Equal("NOT_APPLICABLE",states["cui"]);Assert.Equal("NOT_APPLICABLE",states["taxes"]);Assert.DoesNotContain(Rules.Validate(r,m),p=>p.Blocking);}
 [Fact]public void CustomRulesCannotRemoveRequiredVatFieldsOrRequireHiddenSupplierFields(){var(r,m)=Fixture();m.Add(Master("fieldRules","remove-cui",new{field="cui",state="NOT_APPLICABLE",priority=1,conditions=new{country="RO"}}));m.Add(Master("fieldRules","require-number",new{field="invoice",state="REQUIRED",priority=2,conditions=new{country="RO"}}));Assert.Equal("REQUIRED",Rules.FieldStates(r.Lines[0].Data(),m)["cui"]);var states=Rules.FieldStates(r.Lines[0].Data() with{HasCompanyCui=false},m);Assert.Equal("OPTIONAL",states["invoice"]);Assert.Equal("NOT_APPLICABLE",states["cui"]);}
 [Fact]public void UnknownSupplierNeedsExplicitConfirmationButDoesNotNeedErpAccountAtSubmit(){var(r,m)=Fixture();var d=r.Lines[0].Data();r.Lines[0].Json=Serialization.Write(d with{SupplierConfirmed=false});Assert.Contains(Rules.Validate(r,m),p=>p.Code=="supplier_confirmation");r.Lines[0].Json=Serialization.Write(d);Assert.DoesNotContain(Rules.Validate(r,m),p=>p.Code=="supplier_confirmation"||p.Code=="vendor");Assert.Contains(Rules.Validate(r,m,true),p=>p.Code=="vendor");}
 [Fact]public void CombinedFileMustBeCleanAndCoverEveryReceiptIncludingNewReceipts(){var(r,m)=Fixture();r.Lines[0].Evidence.Clear();var second=new Line{Position=2,EstimatedRon=332,Json=r.Lines[0].Json};r.Lines.Add(second);Assert.Equal(2,Rules.Validate(r,m).Count(p=>p.Code=="evidence"));var bundle=new ReportAttachment{CoveredLines=Serialization.Write(r.Lines.Select(l=>l.Id).ToList())};r.Attachments.Add(bundle);Assert.Equal(2,Rules.Validate(r,m).Count(p=>p.Code=="evidence_scan"));bundle.Scan="Clean";Assert.DoesNotContain(Rules.Validate(r,m),p=>p.Code.StartsWith("evidence"));var third=new Line{Position=3,EstimatedRon=332,Json=second.Json};r.Lines.Add(third);Assert.Contains(Rules.Validate(r,m),p=>p.Code=="evidence"&&p.LineId==third.Id);bundle.CoveredLines=Serialization.Write(r.Lines.Select(l=>l.Id).ToList());Assert.DoesNotContain(Rules.Validate(r,m),p=>p.Code.StartsWith("evidence"));bundle.Archived=true;Assert.Equal(3,Rules.Validate(r,m).Count(p=>p.Code=="evidence"));}
 [Fact]public void MixedVatReceiptExportsSeparateBasesAndTaxCodes(){var(r,m)=Fixture();r.EmployeeId="employee";m.Add(Master("accounting","GENERAL",new{mainAccount="GL",localAccount="LOCAL"}));m.Add(Master("suppliers","18546294",new{vendorAccount="VENDOR"}));m.Add(Master("erpSettings","default",new{approvalReference="TEST",clearingAccount="CLEAR",clearingLocal="CLEAR-LOCAL"}));var rows=new Posting().Build(r,new(){Worker="W"},m).Rows;Assert.Equal(5,rows.Count);Assert.Equal(new[]{"G0","G11","G21"},rows.Take(3).Select(row=>row[17]));Assert.All(rows.Take(3),row=>Assert.Equal("100.00",row[13]));Assert.Equal("300.00",rows[3][14]);Assert.Equal("332.00",rows[4][14]);}
 [Fact]public void AccountingWorkbookContainsExactOriginalBasesAndPaidVat(){var(r,m)=Fixture();using var stream=new MemoryStream(ReceiptAccountingExport.Generate(r,m));using var book=new XLWorkbook(stream);Assert.Equal(2,book.Worksheets.Count);var vat=book.Worksheet("TVA pe cote");Assert.Equal(4,vat.LastRowUsed()!.RowNumber());Assert.Equal(0m,vat.Cell(2,7).GetValue<decimal>());Assert.Equal(11m,vat.Cell(3,7).GetValue<decimal>());Assert.Equal(21m,vat.Cell(4,7).GetValue<decimal>());Assert.All(new[]{2,3,4},row=>Assert.Equal(100m,vat.Cell(row,9).GetValue<decimal>()));Assert.Equal(0m,vat.Cell(2,10).GetValue<decimal>());Assert.Equal(11m,vat.Cell(3,10).GetValue<decimal>());Assert.Equal(21m,vat.Cell(4,10).GetValue<decimal>());Assert.Equal(332m,book.Worksheet("Bonuri").Cell(2,15).GetValue<decimal>());}
 [Fact]public async Task AdditiveAttachmentUpgradeIsIdempotentAndPreservesExistingReports(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var r=new Report{Purpose="Existing report"};db.Reports.Add(r);await db.SaveChangesAsync();foreach(var table in new[]{"DocumentGroups","ExtractionAttempts","DocumentReviews"})await db.Database.ExecuteSqlRawAsync("DROP TABLE \""+table+"\"");await db.Database.ExecuteSqlRawAsync("DROP TABLE \"ReportAttachments\"");await SchemaUpgrades.Apply(db);await SchemaUpgrades.Apply(db);Assert.Equal("Existing report",(await db.Reports.SingleAsync(x=>x.Id==r.Id)).Purpose);db.ReportAttachments.Add(new(){ReportId=r.Id});await db.SaveChangesAsync();Assert.Single(await db.ReportAttachments.ToListAsync());}
 [Fact]public async Task TwoReceiptsWithSameUnknownSupplierCreateOnlyOneRegistrationRequest(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var alice=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var(r,m)=Fixture();r.EmployeeId=alice.Id;r.ManagerId=manager.Id;r.Lines.Add(new(){Position=2,EstimatedRon=332,Json=Serialization.Write(r.Lines[0].Data() with{Invoice="B002"}),Evidence=[new(){Scan="Clean"}]});db.Reports.Add(r);db.Masters.AddRange(m);await db.SaveChangesAsync();var principal=new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity([new(System.Security.Claims.ClaimTypes.NameIdentifier,alice.Id),new(System.Security.Claims.ClaimTypes.Role,"Employee")],"test"));await new Reports(db).Submit(r,principal);await db.SaveChangesAsync();var vendor=Assert.Single(await db.Vendors.ToListAsync());Assert.Equal("18546294",vendor.Cui);Assert.Equal(States.Manager,r.State);}
 [Fact]public async Task SupplierLookupNormalizesCuiAndUsesReceiptDate(){await using var f=new Factory();await f.Seed();using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();db.Masters.Add(Master("suppliers","18546294",new{vendorAccount="TEST"}));await db.SaveChangesAsync();}var c=await Login(f,"alice");var known=await c.GetFromJsonAsync<JsonElement>("/api/suppliers/lookup?cui=RO18546294&date=2026-01-01");Assert.True(known.GetProperty("found").GetBoolean());Assert.Equal("18546294",known.GetProperty("cui").GetString());var earlier=await c.GetFromJsonAsync<JsonElement>("/api/suppliers/lookup?cui=18546294&date=2019-01-01");Assert.False(earlier.GetProperty("found").GetBoolean());Assert.True(earlier.GetProperty("valid").GetBoolean());var invalid=await c.GetFromJsonAsync<JsonElement>("/api/suppliers/lookup?cui=12345&date=2026-01-01");Assert.False(invalid.GetProperty("valid").GetBoolean());}
 [Fact]public async Task CombinedUploadEnforcesCoveragePermissionScanSnapshotAndPack(){await using var f=new Factory();await f.Seed();Guid id,line1,line2;using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var alice=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var r=new Report{EmployeeId=alice.Id,ManagerId=manager.Id,Purpose="Two receipts"};var data=new ExpenseData("",null,"","2026-01-01","RO","Receipt","GENERAL","Receipt","Personal",null,"CC",null,100,"RON",[],false);for(int i=0;i<2;i++)r.Lines.Add(new(){Position=i+1,EstimatedRon=100,Json=Serialization.Write(data)});db.Reports.Add(r);db.Masters.AddRange(Master("expenseTypes","GENERAL",new{}),Master("costCenters","CC",new{erpCode="CC"}));await db.SaveChangesAsync();id=r.Id;line1=r.Lines[0].Id;line2=r.Lines[1].Id;}
 var c=await Login(f,"alice");var bob=await Login(f,"bob");async Task<HttpResponseMessage> Upload(HttpClient client,bool confirmed){using var form=new MultipartFormDataContent();form.Add(new StringContent("1"),"version");form.Add(new StringContent(confirmed?"true":"false"),"coversAll");form.Add(new ByteArrayContent(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a16kAAAAASUVORK5CYII=")),"file","all-receipts.png");client.DefaultRequestHeaders.Remove("Idempotency-Key");client.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());return await client.PostAsync($"/api/reports/{id}/attachments",form);}
 Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Upload(c,false)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Upload(bob,true)).StatusCode);var uploaded=await Upload(c,true);Assert.True(uploaded.IsSuccessStatusCode,await uploaded.Content.ReadAsStringAsync());var file=(await uploaded.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("e").GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.UnprocessableEntity,(await c.GetAsync("/api/report-attachments/"+file)).StatusCode);c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());Assert.Equal(HttpStatusCode.UnprocessableEntity,(await c.PostAsJsonAsync($"/api/reports/{id}/submit",new VersionRequest(2,null))).StatusCode);
 using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var e=await db.ReportAttachments.SingleAsync();Assert.True(e.Covers(line1)&&e.Covers(line2));e.Scan="Clean";await db.SaveChangesAsync();}Assert.Equal(HttpStatusCode.NotFound,(await bob.GetAsync("/api/report-attachments/"+file)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.GetAsync("/api/report-attachments/"+file)).StatusCode);c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());var submit=await c.PostAsJsonAsync($"/api/reports/{id}/submit",new VersionRequest(2,null));Assert.True(submit.IsSuccessStatusCode,await submit.Content.ReadAsStringAsync());using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Contains(file.ToString(),(await db.Snapshots.SingleAsync()).Json);}
 Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync($"/api/reports/{id}/accounting-details")).StatusCode);var finance=await Login(f,"finance");Assert.Equal(HttpStatusCode.OK,(await finance.GetAsync($"/api/reports/{id}/accounting-details")).StatusCode);var pack=await c.GetAsync($"/api/reports/{id}/pack");Assert.True(pack.IsSuccessStatusCode,await pack.Content.ReadAsStringAsync());using var zip=new ZipArchive(new MemoryStream(await pack.Content.ReadAsByteArrayAsync()));Assert.Contains(zip.Entries,e=>e.FullName=="originals/"+file+".png");}
 static async Task<HttpClient> Login(Factory f,string username){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());var login=await c.PostAsJsonAsync("/api/auth/login",new{username,password="Valid-test-Password1!"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return c;}
}
